<?php $dayNames=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'];?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Organization Settings · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'organization',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">ORGANIZATION BUILDER</p><h1>Settings and defaults</h1><p>Control identity, operating hours, department defaults, and validated workforce imports.</p></div><a class="button secondary" href="<?=esc(url_for('organization'))?>">Organization structure</a></header><?php if($notice):?><div class="page-flash <?=$notice['type']?>"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><?php if($error):?><div class="form-alert error"><?=esc($error)?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Organization identity</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_organization_settings"><label>Name<input name="name" value="<?=esc($organizationSettings['display_name']?:$organizationSettings['name'])?>" required></label><label>Timezone<select name="timezone"><?php foreach(['America/New_York','America/Chicago','America/Denver','America/Los_Angeles'] as $tz):?><option <?=$organizationSettings['timezone']===$tz?'selected':''?>><?=$tz?></option><?php endforeach;?></select></label><label>Week starts on<select name="week_starts_on"><?php foreach($dayNames as $n=>$day):?><option value="<?=$n?>" <?=($organizationSettings['week_starts_on']??1)===$n?'selected':''?>><?=$day?></option><?php endforeach;?></select></label><label>Logo text<input name="logo_text" maxlength="40" value="<?=esc($organizationSettings['logo_text']??'')?>" placeholder="Atlas"></label><label>Primary color<input type="color" name="primary_color" value="<?=esc($organizationSettings['primary_color']??'#2867d8')?>"></label><label>Secondary color<input type="color" name="secondary_color" value="<?=esc($organizationSettings['secondary_color']??'#7756d9')?>"></label><h3>Operating hours</h3><?php foreach($dayNames as $n=>$day):$hours=$organizationSettings['operating_hours'][$n]??[];?><div class="planning-row"><strong><?=$day?></strong><label>Open<input type="time" name="open_<?=$n?>" value="<?=esc($hours['open']??'')?>"></label><label>Close<input type="time" name="close_<?=$n?>" value="<?=esc($hours['close']??'')?>"></label></div><?php endforeach;?><button class="button primary">Save settings</button></form></article><article class="panel"><h2>Department defaults</h2><?php foreach($departmentDefaults as $default):?><form method="post" class="planning-row"><?=Csrf::field()?><input type="hidden" name="action" value="save_department_default"><input type="hidden" name="department_id" value="<?=$default['department_id']?>"><span><strong><?=esc($default['name'])?></strong><small>Default shift and minimum staffing</small></span><input type="time" name="default_starts_at" value="<?=esc(substr((string)($default['default_starts_at']??''),0,5))?>"><input type="time" name="default_ends_at" value="<?=esc(substr((string)($default['default_ends_at']??''),0,5))?>"><input type="number" name="minimum_staff" min="0" value="<?=esc($default['minimum_staff']??0)?>"><label class="check-label"><input type="checkbox" name="allow_cross_department" value="1" <?=!empty($default['allow_cross_department'])?'checked':''?>><span>Cross-department</span></label><button class="button secondary">Save</button></form><?php endforeach;?></article><article class="panel span-2"><h2>Validated employee CSV import</h2><p class="auto-routing-note">Required columns: email, role, location, department, position. Atlas validates the entire file before creating any invitations.</p><form method="post" enctype="multipart/form-data" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="import_employees"><label>CSV file<input type="file" name="csv_file" accept=".csv,text/csv"></label><label>Or paste CSV<textarea name="csv_data" rows="7" placeholder="email,role,location,department,position"></textarea></label><button class="button primary">Validate and import</button></form><?php if($importLinks):?><h3>Invitation links</h3><?php foreach($importLinks as $link):?><div class="invitation-result"><input value="<?=esc($link)?>" readonly></div><?php endforeach;?><?php endif;?><h3>Recent batches</h3><?php foreach($importBatches as $batch):?><div class="planning-row"><span><strong>Batch #<?=$batch['id']?> · <?=esc(ucfirst($batch['status']))?></strong><small><?=$batch['valid_count']?> valid · <?=$batch['invalid_count']?> invalid · <?=esc($batch['created_at'])?></small></span></div><?php endforeach;?></article></section></main></body></html>
